INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('inventory.manage','menu.manage','reports.view') WHERE r.name='inventory_manager';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.name IN ('finance.manage','reports.view','billing.manage') WHERE r.name='accountant';
