-- RestoPro — Restaurant POS & ERP SaaS — Complete MySQL Schema (MySQL 8+, utf8mb4)
-- Demo password for all seeded users: password
-- Hash below is a PHP password_hash()/bcrypt hash of "password" (verifiable with password_verify).
CREATE DATABASE IF NOT EXISTS resto_saas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE resto_saas;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS kitchen_tickets,order_payments,order_items,orders,customers,purchase_items,purchase_orders,suppliers,stock_movements,product_ingredients,ingredients,addons,product_variations,products,categories,restaurant_tables,expenses,staff,branches,audit_logs,activities,notifications,support_tickets,announcements,settings,password_resets,invoices,payments,subscriptions,coupons,plans,role_permissions,permissions,roles,users,tenants;
SET FOREIGN_KEY_CHECKS=1;

-- ===== Core SaaS tables =====
CREATE TABLE tenants (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, status ENUM('active','suspended') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_tenants_status(status)) ENGINE=InnoDB;
CREATE TABLE branches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, address VARCHAR(255) NULL, phone VARCHAR(40) NULL, is_main TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_branch_tenant(tenant_id), CONSTRAINT fk_branch_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, branch_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('super_admin','owner','branch_manager','cashier','waiter','kitchen','inventory_manager','accountant') NOT NULL DEFAULT 'cashier', status ENUM('active','suspended') NOT NULL DEFAULT 'active', two_factor_secret VARCHAR(120) NULL, remember_token VARCHAR(64) NULL, email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_users_tenant(tenant_id), INDEX idx_users_branch(branch_id), CONSTRAINT fk_users_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_users_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE password_resets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, token VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_pr_email(email), INDEX idx_pr_token(token)) ENGINE=InnoDB;
CREATE TABLE plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, price_monthly DECIMAL(10,2) NOT NULL DEFAULT 0, price_yearly DECIMAL(10,2) NOT NULL DEFAULT 0, max_branches INT NOT NULL DEFAULT 1, max_users INT NOT NULL DEFAULT 5, max_orders INT NOT NULL DEFAULT 500, features TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, plan_id INT UNSIGNED NOT NULL, status ENUM('trial','active','past_due','cancelled','expired') NOT NULL DEFAULT 'trial', billing_cycle ENUM('monthly','yearly') NOT NULL DEFAULT 'monthly', starts_at DATETIME NULL, ends_at DATETIME NULL, trial_ends_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sub_tenant(tenant_id), CONSTRAINT fk_sub_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_sub_plan FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB;
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, subscription_id INT UNSIGNED NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', method VARCHAR(40) NULL, transaction_ref VARCHAR(120) NULL, paid_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_pay_tenant(tenant_id), CONSTRAINT fk_pay_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_pay_sub FOREIGN KEY(subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE invoices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, payment_id INT UNSIGNED NULL, invoice_number VARCHAR(40) NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, status ENUM('draft','paid','overdue','cancelled') NOT NULL DEFAULT 'draft', issued_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_inv_tenant(tenant_id), CONSTRAINT fk_inv_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_inv_pay FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE coupons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, discount_percent INT NOT NULL DEFAULT 10, max_uses INT NOT NULL DEFAULT 100, used_count INT NOT NULL DEFAULT 0, expires_at DATETIME NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE activities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, description VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_act_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, title VARCHAR(180) NOT NULL, body TEXT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notif_user(user_id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(80) NULL, entity_id INT NULL, ip_address VARCHAR(45) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE support_tickets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, subject VARCHAR(200) NOT NULL, message TEXT NOT NULL, status ENUM('open','in_progress','resolved','closed') NOT NULL DEFAULT 'open', priority ENUM('low','medium','high') NOT NULL DEFAULT 'medium', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ticket_tenant(tenant_id)) ENGINE=InnoDB;
CREATE TABLE announcements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NULL, setting_key VARCHAR(80) NOT NULL, setting_value TEXT NULL, UNIQUE KEY uq_settings (tenant_id,setting_key)) ENGINE=InnoDB;

-- ===== Restaurant tables =====
CREATE TABLE restaurant_tables (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, name VARCHAR(40) NOT NULL, capacity INT NOT NULL DEFAULT 4, status ENUM('available','occupied','reserved') NOT NULL DEFAULT 'available', INDEX idx_table_tenant(tenant_id), INDEX idx_table_branch(branch_id), CONSTRAINT fk_table_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_table_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, sort_order INT NOT NULL DEFAULT 0, INDEX idx_cat_tenant(tenant_id), CONSTRAINT fk_cat_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NULL, name VARCHAR(150) NOT NULL, description TEXT NULL, image_url VARCHAR(255) NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, cost DECIMAL(10,2) NOT NULL DEFAULT 0, track_stock TINYINT(1) NOT NULL DEFAULT 0, stock_quantity DECIMAL(12,2) NOT NULL DEFAULT 0, reorder_level DECIMAL(12,2) NOT NULL DEFAULT 5, is_combo TINYINT(1) NOT NULL DEFAULT 0, is_available TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_prod_tenant(tenant_id), INDEX idx_prod_cat(category_id), CONSTRAINT fk_prod_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_prod_cat FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE product_variations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, price_delta DECIMAL(10,2) NOT NULL DEFAULT 0, INDEX idx_var_product(product_id), CONSTRAINT fk_var_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_var_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE addons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, INDEX idx_addon_product(product_id), CONSTRAINT fk_addon_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_addon_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE ingredients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, unit VARCHAR(20) NOT NULL DEFAULT 'kg', stock_quantity DECIMAL(12,2) NOT NULL DEFAULT 0, cost_per_unit DECIMAL(10,2) NOT NULL DEFAULT 0, reorder_level DECIMAL(12,2) NOT NULL DEFAULT 10, INDEX idx_ing_tenant(tenant_id), CONSTRAINT fk_ing_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE product_ingredients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, ingredient_id INT UNSIGNED NOT NULL, quantity DECIMAL(10,3) NOT NULL DEFAULT 0, UNIQUE KEY uq_prod_ing (product_id,ingredient_id), CONSTRAINT fk_pi_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_pi_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_pi_ing FOREIGN KEY(ingredient_id) REFERENCES ingredients(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, ingredient_id INT UNSIGNED NULL, type ENUM('in','out','adjustment','wastage') NOT NULL DEFAULT 'adjustment', quantity DECIMAL(12,2) NOT NULL DEFAULT 0, reference VARCHAR(80) NULL, note VARCHAR(255) NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_mov_tenant(tenant_id), CONSTRAINT fk_mov_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE suppliers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, contact VARCHAR(100) NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NULL, address VARCHAR(255) NULL, balance DECIMAL(12,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sup_tenant(tenant_id), CONSTRAINT fk_sup_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE purchase_orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NULL, supplier_id INT UNSIGNED NOT NULL, status ENUM('ordered','received','cancelled') NOT NULL DEFAULT 'ordered', total DECIMAL(12,2) NOT NULL DEFAULT 0, received_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_po_tenant(tenant_id), CONSTRAINT fk_po_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_po_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE purchase_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, purchase_order_id INT UNSIGNED NOT NULL, ingredient_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 0, unit_cost DECIMAL(10,2) NOT NULL DEFAULT 0, CONSTRAINT fk_pitem_order FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id) ON DELETE CASCADE, CONSTRAINT fk_pitem_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NULL, address VARCHAR(255) NULL, membership ENUM('regular','silver','gold','vip') NOT NULL DEFAULT 'regular', loyalty_points INT NOT NULL DEFAULT 0, total_spent DECIMAL(12,2) NOT NULL DEFAULT 0, visits INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_cust_tenant(tenant_id), INDEX idx_cust_name(name), CONSTRAINT fk_cust_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE staff (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NULL, role VARCHAR(40) NOT NULL DEFAULT 'cashier', shift VARCHAR(30) NOT NULL DEFAULT 'morning', salary DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_staff_tenant(tenant_id), CONSTRAINT fk_staff_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_staff_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, CONSTRAINT fk_staff_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, table_id INT UNSIGNED NULL, customer_id INT UNSIGNED NULL, user_id INT UNSIGNED NULL, order_number VARCHAR(30) NOT NULL UNIQUE, order_type ENUM('dine-in','takeaway','delivery') NOT NULL DEFAULT 'dine-in', status ENUM('pending','preparing','ready','served','completed','cancelled','refunded') NOT NULL DEFAULT 'pending', payment_status ENUM('paid','unpaid','refunded') NOT NULL DEFAULT 'paid', subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, discount DECIMAL(12,2) NOT NULL DEFAULT 0, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL DEFAULT 0, notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_order_tenant(tenant_id), INDEX idx_order_branch(branch_id), INDEX idx_order_status(status), INDEX idx_order_date(created_at), CONSTRAINT fk_order_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_order_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE, CONSTRAINT fk_order_table FOREIGN KEY(table_id) REFERENCES restaurant_tables(id) ON DELETE SET NULL, CONSTRAINT fk_order_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NULL, product_name VARCHAR(150) NOT NULL, quantity INT NOT NULL DEFAULT 1, unit_price DECIMAL(10,2) NOT NULL DEFAULT 0, line_total DECIMAL(12,2) NOT NULL DEFAULT 0, INDEX idx_oi_order(order_id), CONSTRAINT fk_oi_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_oi_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_oi_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE order_payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, order_id INT UNSIGNED NOT NULL, method VARCHAR(30) NOT NULL DEFAULT 'cash', amount DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('paid','refunded','pending') NOT NULL DEFAULT 'paid', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_op_order(order_id), CONSTRAINT fk_op_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_op_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE kitchen_tickets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, order_id INT UNSIGNED NOT NULL, status ENUM('pending','preparing','ready','completed','cancelled') NOT NULL DEFAULT 'pending', started_at DATETIME NULL, ready_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_kt_tenant(tenant_id), INDEX idx_kt_status(status), CONSTRAINT fk_kt_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_kt_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NULL, title VARCHAR(150) NOT NULL, category VARCHAR(60) NOT NULL DEFAULT 'general', amount DECIMAL(12,2) NOT NULL DEFAULT 0, expense_date DATE NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_exp_tenant(tenant_id), CONSTRAINT fk_exp_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT fk_exp_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;

